import {Button, Tooltip, UnderlineNav, Stack} from '@primer/react'
import {BaseRole, TargetTypeIconMap, type Permission, type TargetType} from '../../types'
import {testIdProps} from '@github-ui/test-id-props'
import {PermissionsSelectPanel} from './PermissionsSelectPanel'
import {BaseRoleMenu} from './BaseRoleMenu'
import {PlusIcon} from '@primer/octicons-react'
import styles from './PermissionsPickerHeader.module.css'
import {useContainerBreakpoint} from '@github-ui/use-container-breakpoint'
import {useState} from 'react'

interface TargetTypeState {
  selected: TargetType
  available: TargetType[]
  onSelect: (type: TargetType) => void
}

interface PermissionsState {
  available: Permission[]
  selected: Permission[]
  countsByTarget: Record<TargetType, number>
  onSelect: (permissions: Permission[]) => void
}

interface BaseRoleState {
  available: BaseRole[]
  selected: BaseRole | undefined
  onSelect: (role: BaseRole) => void
}

export interface PermissionsPickerHeaderProps {
  targetType: TargetTypeState
  permissions: PermissionsState
  baseRole?: BaseRoleState
}

export function PermissionsPickerHeader({targetType, permissions, baseRole}: PermissionsPickerHeaderProps) {
  const selectedTargetTypeName = targetType.selected.toLowerCase()

  const [container, setContainer] = useState<HTMLDivElement | null>(null)
  const breakpoint = useContainerBreakpoint(container)

  return (
    <div ref={setContainer} className={styles.Container}>
      <Stack
        direction={breakpoint(['vertical', 'vertical', 'horizontal'])}
        gap="condensed"
        align={breakpoint(['stretch', 'stretch', 'center'])}
        className="bgColor-muted rounded-top-2 border-bottom px-2"
      >
        <UnderlineNav aria-label="View permissions" className={`flex-1 box-shadow-none ${styles.UnderlineNav}`}>
          {targetType.available.map(type => (
            <UnderlineNav.Item
              as="button"
              type="button"
              aria-current={targetType.selected === type ? 'location' : undefined}
              aria-describedby="permissions-section-label permissions-section-description"
              icon={TargetTypeIconMap[type]}
              counter={permissions.countsByTarget[type] || 0}
              onSelect={() => {
                targetType.onSelect(type)
              }}
              key={type}
              {...testIdProps(`permissions-picker-tab-${type.toLowerCase()}`)}
            >
              {type}
            </UnderlineNav.Item>
          ))}
        </UnderlineNav>
        <Stack
          direction={breakpoint(['vertical', 'vertical', 'horizontal'])}
          justify="end"
          className={styles.ButtonStack}
        >
          {baseRole && <BaseRoleMenu {...baseRole} targetTypeName={selectedTargetTypeName} />}
          {baseRole?.selected === BaseRole.None ? (
            // Disabled "Add permissions" button with tooltip when no base role is selected
            <Tooltip
              text={`Action unavailable: You can only add ${selectedTargetTypeName} permissions once a base ${selectedTargetTypeName} role is selected.`}
              direction="n"
            >
              <Button inactive leadingVisual={PlusIcon}>
                Add permissions
              </Button>
            </Tooltip>
          ) : (
            <PermissionsSelectPanel
              targetType={targetType.selected}
              availableFgps={permissions.available}
              selectedFgps={permissions.selected}
              setSelectedFgps={permissions.onSelect}
            />
          )}
        </Stack>
      </Stack>
    </div>
  )
}
