import {useParams} from '@github-ui/react-router'
import {CustomRoleForm} from '../components/CustomRoleForm'
import {testIdProps} from '@github-ui/test-id-props'
import {CustomRolePage} from '../components/CustomRolePage'
import {customEnterpriseRolesRoute, customEnterpriseRolesEditRoute} from './custom-enterprise-roles-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'

export function CustomEnterpriseRoles() {
  const {slug, role_id} = useParams<{slug: string; role_id?: string}>()
  const basePath = customEnterpriseRolesRoute.generatePath({slug: slug || '', action: ''})
  const queryRoute = role_id ? customEnterpriseRolesEditRoute : customEnterpriseRolesRoute
  const payload = useRouteQuery(queryRoute, 'mainQuery')
  const {availablePermissions, role} = payload.data
  const currentActionPath = role_id ? 'Edit role' : 'Create custom role'

  const navigatePaths = [{href: basePath, text: 'Role management'}]

  return (
    <div {...testIdProps('custom-enterprise-roles-page')}>
      <CustomRolePage
        navigatePaths={navigatePaths}
        currentActionPath={currentActionPath}
        pageTitle="h1"
        form={
          <CustomRoleForm
            basePath={basePath}
            addPermissionsText="Enterprise roles grant access to specific settings and actions in the enterprise account. To manage specific organizations or repositories, use organization or repository roles."
            role={role}
            availablePermissions={availablePermissions}
          />
        }
      />
    </div>
  )
}
