import {testIdProps} from '@github-ui/test-id-props'
import {TargetTypeIconMap, type TargetType} from '../../types'
import {Blankslate} from '@primer/react/experimental'

export interface PermissionsBlankslateProps {
  targetType: TargetType
  noBaseRoleSelected?: boolean
}

export function PermissionsBlankslate({targetType, noBaseRoleSelected = false}: PermissionsBlankslateProps) {
  const IconComponent = TargetTypeIconMap[targetType]
  const targetTypeLowercase = targetType.toLowerCase()

  const getContent = () => {
    if (noBaseRoleSelected) {
      return {
        heading: `Choose a ${targetTypeLowercase} role to inherit`,
        description: `You can only add ${targetTypeLowercase} permissions once a base ${targetTypeLowercase} role is selected.`,
      }
    }

    const messageMap: Record<TargetType, string> = {
      Enterprise: 'Get started by adding permissions to this role.',
      Organization:
        'Organization roles can include repository permissions, which are granted to all repositories in the organization.',
      Repository: 'Get started by adding permissions to this role.',
    }

    return {
      heading: `No ${targetTypeLowercase} permissions added yet`,
      description: messageMap[targetType],
    }
  }

  const {heading, description} = getContent()

  return (
    <Blankslate size="small" spacious {...testIdProps(`permissions-blankslate-${targetTypeLowercase}`)}>
      <Blankslate.Visual>
        <IconComponent size="medium" {...testIdProps('permissions-blankslate-icon')} />
      </Blankslate.Visual>
      <Blankslate.Heading>{heading}</Blankslate.Heading>
      <Blankslate.Description>{description}</Blankslate.Description>
    </Blankslate>
  )
}
