import {useState} from 'react'
import {ConfirmationDialog, Stack} from '@primer/react'
import {MailIcon, PeopleIcon, PersonIcon} from '@primer/octicons-react'
import type {Role} from '../../types'

export interface RoleUpdateConfirmationDialogProps {
  role: Role
  onCancel: () => void
  onUpdateRole: () => void | Promise<void>
}

export function RoleUpdateConfirmationDialog({role, onCancel, onUpdateRole}: RoleUpdateConfirmationDialogProps) {
  const [submitting, setSubmitting] = useState(false)

  function renderAssigneeCounts() {
    const userCount = role.assigneeCount?.users ?? 0
    const teamCount = role.assigneeCount?.teams ?? 0

    // Repository roles display additional assignee details
    const orgMemberCount = role.assigneeCount?.org_members
    const collaboratorCount = role.assigneeCount?.collaborators
    const invitationCount = role.assigneeCount?.invitations
    const showBreakdown = orgMemberCount !== undefined || collaboratorCount !== undefined

    return (
      <div>
        <Stack gap="condensed">
          <div>This role is currently assigned to:</div>
          <div>
            <Stack direction="horizontal" gap="condensed" align="center">
              <PersonIcon className="color-fg-muted" />
              <span>
                <strong>
                  {userCount} <span>{userCount === 1 ? 'person' : 'people'}</span>
                </strong>
                {showBreakdown && (
                  <span>
                    {' '}
                    <span className="color-fg-subtle">
                      (<span>{orgMemberCount ?? 0}</span> org <span>{orgMemberCount === 1 ? 'member' : 'members'}</span>
                      <span>, </span>
                      <span>{collaboratorCount ?? 0}</span> <span>outside</span>{' '}
                      <span>{collaboratorCount === 1 ? 'collaborator' : 'collaborators'}</span>)
                    </span>
                  </span>
                )}
              </span>
            </Stack>
            <Stack direction="horizontal" gap="condensed" align="center">
              <PeopleIcon className="color-fg-muted" />
              <strong>
                {teamCount} <span>{teamCount === 1 ? 'team' : 'teams'}</span>
              </strong>
            </Stack>
            {invitationCount !== undefined && invitationCount > 0 && (
              <Stack direction="horizontal" gap="condensed" align="center">
                <MailIcon className="color-fg-muted" />
                <strong>
                  {invitationCount} <span>{invitationCount === 1 ? 'invitation' : 'invitations'}</span>
                </strong>
              </Stack>
            )}
          </div>
        </Stack>
      </div>
    )
  }

  return (
    <ConfirmationDialog
      title="Confirm role update"
      width="large"
      onClose={async gesture => {
        if (gesture === 'confirm') {
          setSubmitting(true)
          await onUpdateRole()
        } else {
          onCancel()
        }
      }}
      confirmButtonContent="Update role"
      confirmButtonType="primary"
      confirmButtonLoading={submitting}
    >
      <Stack gap="condensed">
        <div>
          Updating the <strong>{role.name}</strong> role may change permissions for all the people and teams assigned to
          it.
        </div>
        {renderAssigneeCounts()}
      </Stack>
    </ConfirmationDialog>
  )
}
