import {mainQuery} from '@github-ui/react-core/future/main-query'
import {customRolesAppBuilder} from '../config/app-builder'
import type {CustomRolePayload} from '../types'

export const customEnterpriseRolesRoute = customRolesAppBuilder.createQueryRouteConfig('customEnterpriseRolesRoute', {
  path: '/enterprises/:slug/enterprise_roles/:action',
  queries: [mainQuery<CustomRolePayload>()],
})

export const customEnterpriseRolesEditRoute = customRolesAppBuilder.createQueryRouteConfig(
  'customEnterpriseRolesEditRoute',
  {
    path: '/enterprises/:slug/enterprise_roles/:role_id/:action',
    queries: [mainQuery<CustomRolePayload>()],
  },
)
